package frontmatter

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// ErrNoDate is returned when a page's front matter has no date field.
var ErrNoDate = errors.New("front matter has no date")

// dateLayouts are the accepted forms of the `date:` field, most specific first.
var dateLayouts = []string{
	time.RFC3339,
	"2006-01-02T15:04:05",
	"2006-01-02",
}

// parseFrontMatterDate turns the raw `date:` value of a page's front matter into a timestamp.
// file is the page's path, used only in the error message.
func parseFrontMatterDate(file, raw string) (time.Time, error) {
	value := strings.Trim(strings.TrimSpace(raw), `"'`)
	if value == "" {
		return time.Time{}, fmt.Errorf("%s: %w", file, ErrNoDate)
	}

	for _, layout := range dateLayouts {
		parsed, err := time.Parse(layout, value)
		if err == nil {
			return parsed.UTC(), nil
		}
	}

	return time.Time{}, fmt.Errorf("invalid date in %s: %q", file, value)
}

// PageDate reads the date field from parsed front matter.
func PageDate(file string, fields map[string]string) (time.Time, error) {
	raw, ok := fields["date"]
	if !ok {
		return time.Time{}, fmt.Errorf("%s: %w", file, ErrNoDate)
	}

	return parseFrontMatterDate(file, raw)
}

package frontmatter

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestParseFrontMatterDate(t *testing.T) {
	t.Parallel()

	valid := []struct {
		name string
		raw  string
		want time.Time
	}{
		{"rfc3339 with Z", "2026-03-14T09:30:00Z", time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
		{"rfc3339 with offset", "2026-03-14T11:30:00+02:00", time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
		{"date only", "2026-03-14", time.Date(2026, 3, 14, 0, 0, 0, 0, time.UTC)},
		{"quoted value", `"2026-03-14T09:30:00Z"`, time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
	}
	for _, tc := range valid {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got, err := parseFrontMatterDate("posts/pi-day.md", tc.raw)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !got.Equal(tc.want) || got.Location() != time.UTC {
				t.Fatalf("got %v, want %v in UTC", got, tc.want)
			}
		})
	}

	t.Run("invalid names the file", func(t *testing.T) {
		t.Parallel()
		_, err := parseFrontMatterDate("posts/bad.md", "14 March 2026")
		if err == nil || !strings.Contains(err.Error(), "invalid date in posts/bad.md") {
			t.Fatalf("want an error naming the file, got %v", err)
		}
	})
}

func TestPageDate(t *testing.T) {
	t.Parallel()

	t.Run("missing date", func(t *testing.T) {
		t.Parallel()
		_, err := PageDate("posts/draft.md", map[string]string{"title": "Draft"})
		if !errors.Is(err, ErrNoDate) {
			t.Fatalf("want ErrNoDate, got %v", err)
		}
	})
}

